frappe.listview_settings['Item'] = frappe.listview_settings['Item'] || {};
const _orig_onload = frappe.listview_settings['Item'].onload;
frappe.listview_settings['Item'].onload = function(listview) {
    if (_orig_onload) _orig_onload.call(this, listview);
    const run_publish = () => {
        const selected = listview.get_checked_items().map(d => d.name);
        if (!selected.length) {
            frappe.msgprint(__('Please tick at least one Item checkbox first.'));
            return;
        }
        frappe.confirm(
            __('Publish {0} selected item(s) to the Webshop?', [selected.length]),
            () => {
                frappe.call({
                    method: 'promo_theme.api.bulk_publish_items_to_website',
                    args: { item_codes: selected },
                    freeze: true,
                    freeze_message: __('Publishing {0} items to Website...', [selected.length]),
                    callback: (r) => {
                        const res = r.message || {};
                        frappe.show_alert({
                            message: __('Done: {0} created, {1} published on Website.', [res.created || 0, res.published || 0]),
                            indicator: 'green'
                        }, 6);
                        listview.refresh();
                    }
                });
            }
        );
    };
    listview.page.add_action_item(__('Publish to Website'), run_publish);
    listview.page.add_inner_button(__('Publish to Website'), run_publish);
};
